//! AArch32 decoders generated from Arm's machine-readable specification: A32 (ARM) and T32 (Thumb).
//!
//! `a32_spec.rs`, `t16_spec.rs` and `t32_spec.rs` are generated by `tools/armgen`; the last two hold T32's 16-bit
//! and 32-bit encodings. Operand semantics, which the open-source specification leaves out, are written by hand
//! in `operands.rs`.

#[allow(clippy::all)]
#[rustfmt::skip]
mod a32_spec;
mod flow;
#[rustfmt::skip]
mod m_profile;
mod operands;
mod spec_types;
#[allow(clippy::all)]
#[rustfmt::skip]
mod t16_spec;
#[allow(clippy::all)]
#[rustfmt::skip]
mod t32_spec;
mod wide;

use crate::mrs::{self, Encoding, State, Syntax, Tables, mnemonic};

pub use crate::mrs::LabelStyle;
pub use flow::Aarch32Disassembler;

/// Which table an instruction comes from.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Set {
    A32,
    /// A 16-bit T32 instruction.
    T16,
    /// A 32-bit T32 instruction, with its first halfword in bits 31..16.
    T32,
}

impl Set {
    fn tables(self) -> &'static Tables {
        match self {
            Set::A32 => &a32_spec::TABLES,
            Set::T16 => &t16_spec::TABLES,
            Set::T32 => &t32_spec::TABLES,
        }
    }

    pub fn size(self) -> u8 {
        if self == Set::T16 { 2 } else { 4 }
    }
}

/// The IT block state (ITSTATE): the base condition and mask an IT instruction sets up for the up to four
/// instructions after it.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct ItState(u8);

impl ItState {
    pub fn new(firstcond: u8, mask: u8) -> Self {
        Self((firstcond << 4) | (mask & 0xf))
    }

    pub fn in_block(self) -> bool {
        self.0 & 0xf != 0
    }

    /// The condition of the instruction the state applies to, inside an IT block.
    pub fn condition(self) -> Option<u8> {
        self.in_block().then_some(self.0 >> 4)
    }

    /// The state for the next instruction (`ITAdvance`).
    pub fn advance(self) -> Self {
        if self.0 & 0x7 == 0 { Self(0) } else { Self((self.0 & 0xe0) | ((self.0 << 1) & 0x1f)) }
    }

    /// Whether this is the last instruction of its IT block.
    pub fn last_in_block(self) -> bool {
        self.0 & 0xf == 0x8
    }
}

/// Whether a Thumb halfword starts a 32-bit instruction.
pub fn is_wide(halfword: u16) -> bool {
    matches!(halfword >> 11, 0b11101..=0b11111)
}

#[derive(Clone, Copy)]
pub struct Decoded {
    pub word: u32,
    pub set: Set,
    pub encoding: &'static Encoding,
    pub syntax: &'static Syntax,
    /// The IT state the instruction executes in (T32 only).
    pub it: ItState,
}

impl Decoded {
    pub fn field(&self, name: &str) -> Option<u64> {
        self.encoding.field(self.word, name)
    }

    pub fn size(&self) -> u8 {
        self.set.size()
    }

    /// The displayed mnemonic, uppercase as the specification writes it.
    pub fn mnemonic(&self) -> &'static str {
        mnemonic(self.syntax)
    }
}

fn decode_word(set: Set, word: u32, it: ItState, profile: Profile) -> Option<Decoded> {
    let state = State { in_it_block: it.in_block() };
    let tables = set.tables();
    let encoding = match profile {
        Profile::A => tables.lookup(word, state)?,
        // The A-profile tables leave M-profile system-register moves (`msr basepri, r0`) unallocated, and allocate
        // A-profile-only instructions that are UNDEFINED on an M-profile processor.
        // Every MRS/MSR word follows the M-profile rules, including the APSR forms the A-profile tables also hold.
        Profile::M if set == Set::T32 && m_profile::claims(word) => m_profile::lookup(word)?,
        Profile::M => tables.lookup(word, state).filter(|encoding| !m_profile::undefined(encoding, word))?,
    };
    // Aliases that spell out `.W` are the assembler's width-qualified synonyms of another alias; `format` adds
    // the qualifier where LLVM prints it.
    let unqualified = |alias: &mrs::Alias| {
        !alias.syntax.tokens.iter().any(|token| matches!(token, mrs::Token::Text(text) if text.contains(".W")))
    };
    let mut syntax = tables.preferred_syntax_among(encoding, word, state, &unqualified);
    // Aliases that address a label are PC-relative; the specification leaves their condition (base register
    // PC) out.
    let names_label = syntax.operands.iter().any(|operand| operand.name == "<label>");
    if names_label && encoding.field(word, "Rn").is_some_and(|rn| rn != 15) {
        syntax = &encoding.syntax;
    }
    Some(Decoded { word, set, encoding, syntax, it })
}

/// Which architecture profile's T32 instruction set to decode.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Profile {
    /// A/R-profile: the generated specification tables as they are.
    A,
    /// ARMv6-M/ARMv7-M(E): without A-profile-only groups, with the M-profile system-register moves.
    M,
}

/// Decodes an A32 instruction word, or `None` when it is unallocated.
pub fn decode_a32(word: u32) -> Option<Decoded> {
    decode_word(Set::A32, word, ItState::default(), Profile::A)
}

fn decode_thumb(first: u16, second: Option<u16>, it: ItState, profile: Profile) -> Option<Decoded> {
    if is_wide(first) {
        decode_word(Set::T32, (u32::from(first) << 16) | u32::from(second?), it, profile)
    } else {
        decode_word(Set::T16, u32::from(first), it, profile)
    }
}

/// Decodes the A-profile T32 instruction that starts with `first`, reading `second` when it is 32-bit. `None`
/// when it is unallocated, or 32-bit without a second halfword.
pub fn decode_t32(first: u16, second: Option<u16>, it: ItState) -> Option<Decoded> {
    decode_thumb(first, second, it, Profile::A)
}

/// [`decode_t32`] for an ARMv6-M/ARMv7-M(E) processor: the M-profile `MRS`/`MSR` special registers decode, and
/// A-profile-only instructions (BLX to A32, Advanced SIMD, SETEND, SRS/RFE, ERET, SMC/HVC, banked registers,
/// LDREXD/STREXD, 32-bit CPS, `cpsie a`) are UNDEFINED.
pub fn decode_t32_m(first: u16, second: Option<u16>, it: ItState) -> Option<Decoded> {
    decode_thumb(first, second, it, Profile::M)
}

/// Renders a decoded instruction at `address`, or `None` when an operand value has no rendering (the encoding
/// is UNDEFINED for it).
pub fn format(decoded: &Decoded, address: u64, labels: LabelStyle) -> Option<String> {
    // LLVM spells PC-relative loads and A32's ADR with PC as a register (`ldr r0, [pc, #8]`, `add r0, pc, #8`),
    // as the specification's aliases do; absolute labels name the address instead. It always names the
    // wide-immediate forms (MOVW, ADDW, SUBW).
    let aliases = decoded.encoding.aliases;
    let base = mnemonic(&decoded.encoding.syntax);
    let explicit_width = aliases.iter().find(|alias| mnemonic(&alias.syntax).strip_suffix('W') == Some(base));
    let tables = decoded.set.tables();
    let state = State { in_it_block: decoded.it.in_block() };
    let applies = |id| (tables.condition)(id, decoded.word, state);
    // Post-indexed and writeback forms keep their own syntax, which shows the indexing. The aliases that name
    // PC carry no condition of their own: they apply when the base register is PC (or there is none, as in ADR).
    let indexed = decoded.field("P") == Some(0) || decoded.field("W") == Some(1);
    let base_is_pc = decoded.field("Rn").is_none_or(|rn| rn == 15);
    let pc_spelled = aliases
        .iter()
        .filter(|_| !indexed && base_is_pc)
        .find(|alias| applies(alias.condition) && spells_pc(&alias.syntax, decoded.set));
    let syntax = match (labels, explicit_width, pc_spelled) {
        (_, Some(alias), _) => &alias.syntax,
        (LabelStyle::Relative, _, Some(alias)) => &alias.syntax,
        _ => decoded.syntax,
    };
    let text = mrs::render_with_fallback(syntax, &decoded.encoding.syntax, &|syntax, operand| {
        let decoded = Decoded { syntax, ..*decoded };
        operands::render(&operands::Context { decoded: &decoded, address, labels }, operand)
    })?;
    Some(normalize(text, decoded))
}

fn normalize(mut text: String, decoded: &Decoded) -> String {
    for (from, to) in [(" ,", ","), (" ]", "]"), ("  ", " "), ("}^", "} ^"), ("#0.0", "#0")] {
        text = text.replace(from, to);
    }
    if decoded.mnemonic() == "CLRBHB" {
        let end = text.find(' ').unwrap_or(text.len());
        let suffix = text[6..end].to_owned();
        text = format!("hint{suffix} #22");
    }
    let key = (decoded.encoding.name, decoded.mnemonic());
    if decoded.set == Set::T32 && wide::WIDE.binary_search(&key).is_ok() {
        // The qualifier follows the mnemonic and any condition (`addeq.w`).
        let end = text.find(' ').unwrap_or(text.len());
        if !text[..end].ends_with(".w") {
            text.insert_str(end, ".w");
        }
    }
    text
}

/// Whether an alias names PC as a register: loads (`[PC, #8]`) and A32's ADR as ADD or SUB (`PC, #8`); T32's
/// ADR keeps its name.
fn spells_pc(syntax: &Syntax, set: Set) -> bool {
    syntax.tokens.iter().any(|token| match token {
        mrs::Token::Text(text) => text.contains("[PC") || (set == Set::A32 && text.contains("PC, #")),
        _ => false,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decision_trees_agree_with_linear_scans() {
        let mut state = 7u64;
        for set in [Set::A32, Set::T16, Set::T32] {
            let tables = set.tables();
            for in_it_block in [false, true] {
                let state_bits = State { in_it_block };
                for _ in 0..20_000 {
                    state = state.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
                    let word = (state >> 32) as u32 & if set == Set::T16 { 0xffff } else { u32::MAX };
                    let tree = tables.lookup(word, state_bits).map(|encoding| encoding.name);
                    let linear = tables.lookup_linear(word, state_bits).map(|encoding| encoding.name);
                    assert_eq!(tree, linear, "{set:?} {word:#010x}");
                }
            }
        }
    }

    #[test]
    fn every_encoding_formats_without_panicking() {
        let mut state = 11u64;
        for set in [Set::A32, Set::T16, Set::T32] {
            for encoding in set.tables().encodings.iter().chain(m_profile::ENCODINGS.iter().filter(|_| set == Set::T32))
            {
                for _ in 0..64 {
                    state = state.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
                    let word = ((state >> 32) as u32 & !encoding.mask) | encoding.value;
                    let word = if set == Set::T16 { word & 0xffff } else { word };
                    for it in [ItState::default(), ItState::new(0, 0x8)] {
                        for profile in [Profile::A, Profile::M] {
                            if let Some(decoded) = decode_word(set, word, it, profile) {
                                let _ = format(&decoded, 0x1000, LabelStyle::Relative);
                            }
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn it_state_advances_through_its_block() {
        // ITTE EQ: then, then, else.
        let it = ItState::new(0b0000, 0b0110);
        assert_eq!(it.condition(), Some(0));
        let it = it.advance();
        assert_eq!(it.condition(), Some(0));
        let it = it.advance();
        assert_eq!(it.condition(), Some(1));
        assert!(it.last_in_block());
        assert!(!it.advance().in_block());
    }
}
